+/** A fetch wrapper that parses JSON, enforces a timeout, and retries per policy. */

 export class HttpError extends Error {
   constructor(public readonly status: number, public readonly url: string) {
     super(`HTTP ${status} from ${url}`);
     this.name = "HttpError";
   }
 }

 export class TimeoutError extends Error {
   constructor(public readonly url: string, public readonly timeoutMs: number) {
     super(`timed out after ${timeoutMs}ms fetching ${url}`);
     this.name = "TimeoutError";
   }
 }

+/** Decides whether a failed attempt should be tried again. */
+export interface RetryPolicy {
+  /** `attempt` is 1-based; return true to try again after `err`. */
+  shouldRetry(attempt: number, err: unknown): boolean;
+}
+
+export const noRetry: RetryPolicy = { shouldRetry: () => false };
+
+export function retryOnTimeout(maxRetries = 1): RetryPolicy {
+  return {
+    shouldRetry: (attempt, err) => attempt <= maxRetries && err instanceof TimeoutError,
+  };
+}
+
 export interface FetchOptions {
   timeoutMs?: number;
   headers?: Record<string, string>;
 }

-const DEFAULT_TIMEOUT_MS = 5000;
+export interface ClientOptions extends FetchOptions {
+  /** Policy consulted after each failed attempt. */
+  retry?: RetryPolicy;
+  /** Base delay between attempts; multiplied by the attempt number. */
+  backoffMs?: number;
+}

-export async function fetchJson<T>(url: string, opts: FetchOptions = {}): Promise<T> {
-  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
-  const controller = new AbortController();
-  const timer = setTimeout(() => controller.abort(), timeoutMs);
