-    if (!res.ok) {
-      throw new HttpError(res.status, url);
+type ResolvedOptions = Required<ClientOptions>;
+
+const DEFAULT_OPTIONS: ResolvedOptions = {
+  timeoutMs: 5000,
+  headers: {},
+  retry: retryOnTimeout(1),
+  backoffMs: 0,
+};
+
+const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
+
+export class FetchClient {
+  private readonly options: ResolvedOptions;
+
+  constructor(options: ClientOptions = {}) {
+    this.options = { ...DEFAULT_OPTIONS, ...stripUndefined(options) };
+  }
+
+  async fetchJson<T>(url: string, overrides: ClientOptions = {}): Promise<T> {
+    const opts: ResolvedOptions = { ...this.options, ...stripUndefined(overrides) };
+    for (let attempt = 1; ; attempt++) {
+      try {
+        return await this.attempt<T>(url, opts);
+      } catch (err) {
+        if (!opts.retry.shouldRetry(attempt, err)) {
+          throw err;
+        }
+        if (opts.backoffMs > 0) {
+          await sleep(opts.backoffMs * attempt);
+        }
+      }
     }
-    return (await res.json()) as T;
-  } catch (err) {
-    if ((err as Error).name === "AbortError") {
-      throw new TimeoutError(url, timeoutMs);
+  }
+
+  private async attempt<T>(url: string, opts: ResolvedOptions): Promise<T> {
+    const controller = new AbortController();
+    const timer = setTimeout(() => controller.abort(), opts.timeoutMs);
+    try {
+      const res = await fetch(url, { signal: controller.signal, headers: opts.headers });
+      if (!res.ok) {
+        throw new HttpError(res.status, url);
+      }
+      return (await res.json()) as T;
+    } catch (err) {
+      if ((err as Error).name === "AbortError") {
+        throw new TimeoutError(url, opts.timeoutMs);
+      }
+      throw err;
+    } finally {
+      clearTimeout(timer);
     }
-    throw err;
-  } finally {
-    clearTimeout(timer);
   }
 }
+
+function stripUndefined<T extends object>(obj: T): Partial<T> {
+  return Object.fromEntries(Object.entries(obj).filter(([, v]) => v !== undefined)) as Partial<T>;
+}
+
+const defaultClient = new FetchClient();
+
+/** Fetch JSON with the default client, which retries once on timeout. */
+export function fetchJson<T>(url: string, opts: FetchOptions = {}): Promise<T> {
+  return defaultClient.fetchJson<T>(url, opts);
+}
